import { resolveAdapter } from '../registry';

describe('registry — optional provider SDK not installed', () => {
  it('throws an actionable install message instead of a raw module error', () => {
    let thrown: Error | undefined;
    try {
      resolveAdapter('vgs');
    } catch (error) {
      thrown = error as Error;
    }
    expect(thrown).toBeDefined();
    expect(thrown?.message).toMatch(/@vgs\/collect-react-native/);
    expect(thrown?.message).toMatch(/not installed/i);
  });
});

import type { TurboModule, CodegenTypes } from 'react-native';
import { TurboModuleRegistry } from 'react-native';

export type CommandEvent = {
  rootTag: CodegenTypes.Int32;
  formId: string;
  commandId: string;
  name: string;
  elementType?: string;
  providerData?: string;
};

export interface Spec extends TurboModule {
  emitFieldEvent(
    rootTag: CodegenTypes.Int32,
    eventName: string,
    payload: CodegenTypes.UnsafeObject
  ): void;
  emitFormEvent(
    rootTag: CodegenTypes.Int32,
    eventName: string,
    payload: CodegenTypes.UnsafeObject
  ): void;

  readonly onCommand: CodegenTypes.EventEmitter<CommandEvent>;
}

export default TurboModuleRegistry.get<Spec>('HyperPaymentMethodsModule');

import { Fragment, useEffect, useImperativeHandle } from 'react';
import { Text } from 'react-native';
import { fieldChange } from '../core/fieldChange';
import type { FieldChangeInput } from '../core/fieldChange';
import type {
  ProviderAdapter,
  ProviderFieldProps,
  ProviderHostProps,
} from '../core/ProviderAdapter';
import type {
  CardDetails,
  ElementType,
  TokenizeResult,
  VaultType,
} from '../core/types';

export interface MockAdapterOptions {
  vaultType?: VaultType;

  readyDelayMs?: number;

  neverReady?: boolean;

  failOnInit?: unknown;

  tokenizeResult?: TokenizeResult;

  fieldState?: FieldChangeInput;

  cardDetails?: Partial<CardDetails>;

  onTokenize?: () => void;

  onFieldCommand?: (
    elementType: ElementType,
    name: 'focus' | 'blur' | 'clear'
  ) => void;
}

export function createMockAdapter(
  options: MockAdapterOptions = {}
): ProviderAdapter {
  const vaultType: VaultType = options.vaultType ?? 'vgs';

  function Host({
    onReady,
    onError,
    onCardDetails,
    children,
  }: ProviderHostProps) {
    useEffect(() => {
      if (options.failOnInit !== undefined) {
        onError(options.failOnInit);
        return;
      }
      if (options.neverReady) return;

      const delay = options.readyDelayMs ?? 0;
      const timer = setTimeout(() => {
        onReady({ mock: true });
        if (options.cardDetails) onCardDetails?.(options.cardDetails);
      }, delay);
      return () => clearTimeout(timer);
    }, [onReady, onError, onCardDetails]);

    return <Fragment>{children}</Fragment>;
  }

  function Field({
    elementType,
    onChange,
    styles,
    savedCard,
    placeholder,
    cvcIcon,
    cardBrandIcon,
    label,
    labelBehavior,
    errorDisplay,
    unstyled,
    testID,
    fieldRef,
  }: ProviderFieldProps) {
    useImperativeHandle(
      fieldRef,
      () => ({
        focus: () => options.onFieldCommand?.(elementType, 'focus'),
        blur: () => options.onFieldCommand?.(elementType, 'blur'),
        clear: () => options.onFieldCommand?.(elementType, 'clear'),
      }),
      [elementType]
    );
    const state = options.fieldState;
    useEffect(() => {
      if (state) onChange?.(fieldChange(elementType, state));
    }, [elementType, onChange, state]);
    return (
      <Text
        testID={`mock-field-${elementType}`}
        style={styles?.container}
        accessibilityLabel={
          savedCard
            ? `saved:${savedCard.paymentMethodToken}:${savedCard.paymentMethodData?.card?.cardNetwork ?? ''}`
            : undefined
        }
        accessibilityHint={cvcIcon}
        accessibilityValue={{
          /* Every forwarded prop, for tests to read back; JSON drops the unset ones. */
          text: JSON.stringify({
            placeholder,
            cardBrandIcon,
            label,
            labelBehavior,
            errorDisplay,
            unstyled,
            testID,
          }),
        }}
      >{`mock:${elementType}`}</Text>
    );
  }

  return {
    vaultType,
    validateVaultData: (raw) => raw,
    createCollector: async () => {
      if (options.failOnInit !== undefined) throw options.failOnInit;
      if (options.readyDelayMs) {
        await new Promise((resolve) =>
          setTimeout(resolve, options.readyDelayMs)
        );
      }
      return { mock: true };
    },
    Host,
    Field,
    tokenize: async () => {
      options.onTokenize?.();
      return (
        options.tokenizeResult ?? {
          status: 'success',
          vaultType,
          data: { tokens: { card_number: 'tok_mock' } },
        }
      );
    },
  };
}

import { jest } from '@jest/globals';

const EMPTY_SVG = '<svg xmlns="http://www.w3.org/2000/svg"></svg>';

export interface MockApiReply {
  ok?: boolean;
  status?: number;
  body?: unknown;
}

/* The vault fetches its brand icons as well as calling the API. Icons always
   get a parseable answer, so a test decides only what the API says, and
   nothing here can reach the real network. */
export function mockFetch(api: MockApiReply = {}) {
  const original = globalThis.fetch;
  const mock = jest.fn(async (url: unknown, _init?: unknown) => {
    const isIcon = String(url).endsWith('.svg');
    const body = isIcon ? EMPTY_SVG : JSON.stringify(api.body ?? {});
    return {
      ok: isIcon ? true : (api.ok ?? true),
      status: isIcon ? 200 : (api.status ?? 200),
      headers: { get: () => (isIcon ? 'image/svg+xml' : 'application/json') },
      json: async () => (isIcon ? {} : (api.body ?? {})),
      text: async () => body,
    };
  });
  globalThis.fetch = mock as unknown as typeof fetch;

  return {
    apiCalls: () =>
      mock.mock.calls.filter(([url]) => !String(url).endsWith('.svg')),
    restore: () => {
      globalThis.fetch = original;
    },
  };
}

import { describe, it, expect, jest } from '@jest/globals';
import { HyperswitchPaymentMethods } from '../HyperswitchPaymentMethods';
import { registerForm } from '../core/formRegistry';
import type { TokenizeResult } from '../core/types';

const ok: TokenizeResult = { status: 'success', vaultType: 'skyflow' };

describe('HyperswitchPaymentMethods.tokenize', () => {
  it('answers incomplete_field_set when no form is registered for the id', async () => {
    const result = await HyperswitchPaymentMethods.tokenize('absent');
    expect(result.status).toBe('validation_error');
    expect(result.status === 'validation_error' && result.error).toEqual({
      code: 'incomplete_field_set',
      message: expect.stringContaining('<CardForm id="absent">'),
      type: 'validation_error',
    });
  });

  it('routes to the registered form and forwards providerData', async () => {
    const tokenize = jest.fn(async () => ok);
    const off = registerForm('checkout', tokenize);
    try {
      const result = await HyperswitchPaymentMethods.tokenize('checkout', {
        token: 'abc',
      });
      expect(tokenize).toHaveBeenCalledWith({ token: 'abc' });
      expect(result).toEqual(ok);
    } finally {
      off();
    }
  });
});

import { describe, it, expect } from '@jest/globals';
import { registerAdapter, resolveAdapter } from '../registry';
import type { ProviderAdapter } from '../../core/ProviderAdapter';
import type { VaultType } from '../../core/types';

function fakeAdapter(vaultType: VaultType): ProviderAdapter {
  return {
    vaultType,
    validateVaultData: (raw) => raw,
    Host: () => null,
    Field: () => null,
    tokenize: async () => ({ status: 'success', vaultType }),
  };
}

const UNREGISTERED = 'no_such_provider' as VaultType;

describe('adapter registry', () => {
  it('throws a helpful error when no adapter exists for a vault type', () => {
    expect(() => resolveAdapter(UNREGISTERED)).toThrow(/no provider adapter/i);
  });

  it('resolves a registered adapter', () => {
    const adapter = fakeAdapter('vgs');
    const off = registerAdapter(adapter);
    try {
      expect(resolveAdapter('vgs')).toBe(adapter);
    } finally {
      off();
    }
  });

  it('unregister removes the adapter', () => {
    const adapter = fakeAdapter(UNREGISTERED);
    const off = registerAdapter(adapter);
    off();
    expect(() => resolveAdapter(UNREGISTERED)).toThrow(/no provider adapter/i);
  });

  it('stale unregister does not remove a newer registration for the same type', () => {
    const first = fakeAdapter('evervault');
    const second = fakeAdapter('evervault');
    const offFirst = registerAdapter(first);
    const offSecond = registerAdapter(second);
    offFirst();
    try {
      expect(resolveAdapter('evervault')).toBe(second);
    } finally {
      offSecond();
    }
  });
});

import { describe, it, expect } from '@jest/globals';
import { registerForm, getFormTokenize } from '../formRegistry';
import type { TokenizeResult } from '../types';

const ok: TokenizeResult = { status: 'success', vaultType: 'vgs' };

describe('formRegistry', () => {
  it('returns undefined for an unregistered id', () => {
    expect(getFormTokenize('nope')).toBeUndefined();
  });

  it('routes to the registered tokenize function', async () => {
    let called = false;
    const off = registerForm('checkout', async () => {
      called = true;
      return ok;
    });
    try {
      const fn = getFormTokenize('checkout');
      expect(fn).toBeDefined();
      await fn!();
      expect(called).toBe(true);
    } finally {
      off();
    }
  });

  it('unregister removes the registration', () => {
    const off = registerForm('temp', async () => ok);
    off();
    expect(getFormTokenize('temp')).toBeUndefined();
  });

  it('stale unregister does not evict a newer registration for the same id', async () => {
    const offA = registerForm('dup', async () => ({ ...ok, vaultType: 'vgs' }));
    const second = async (): Promise<TokenizeResult> => ({
      ...ok,
      vaultType: 'skyflow',
    });
    const offB = registerForm('dup', second);
    offA();
    try {
      const fn = getFormTokenize('dup');
      expect(fn).toBe(second);
    } finally {
      offB();
    }
  });
});

import { describe, it, expect } from '@jest/globals';
import { createDeferred } from '../deferred';

describe('createDeferred', () => {
  it('resolves the promise with the provided value', async () => {
    const d = createDeferred<number>();
    d.resolve(42);
    await expect(d.promise).resolves.toBe(42);
  });

  it('rejects the promise with the provided error', async () => {
    const d = createDeferred<number>();
    const err = new Error('boom');
    d.reject(err);
    await expect(d.promise).rejects.toBe(err);
  });

  it('starts unsettled and reports settled after resolve', () => {
    const d = createDeferred<void>();
    expect(d.settled).toBe(false);
    d.resolve();
    expect(d.settled).toBe(true);
  });

  it('keeps the first settlement (resolve after resolve is ignored)', async () => {
    const d = createDeferred<number>();
    d.resolve(1);
    d.resolve(2);
    await expect(d.promise).resolves.toBe(1);
  });
});

import { describe, it, expect, jest } from '@jest/globals';
import { createFormSession } from '../formSession';
import type { ProviderAdapter } from '../ProviderAdapter';
import type { TokenizeResult } from '../types';

const success: TokenizeResult = {
  status: 'success',
  vaultType: 'vgs',
  data: { tokens: { card_number: 'tok_123' } },
};

const errorOf = (result: TokenizeResult) =>
  result.status === 'success' ? undefined : result.error;

function fakeAdapter(
  tokenize: ProviderAdapter['tokenize'] = async () => success
): ProviderAdapter {
  return {
    vaultType: 'vgs',
    validateVaultData: (raw) => raw,
    Host: () => null,
    Field: () => null,
    tokenize,
  };
}

describe('createFormSession', () => {
  it('starts in the initializing state', () => {
    const session = createFormSession(fakeAdapter());
    expect(session.status).toBe('initializing');
  });

  it('becomes ready once a collector attaches', () => {
    const session = createFormSession(fakeAdapter());
    session.attachCollector({});
    expect(session.status).toBe('ready');
  });

  it('delegates tokenize to the adapter once ready, passing providerData', async () => {
    const tokenize = jest.fn(async () => success);
    const collector = { id: 'collector' };
    const session = createFormSession(fakeAdapter(tokenize));
    session.attachCollector(collector);

    const result = await session.tokenize({ extra: 1 });

    expect(result).toEqual(success);
    expect(tokenize).toHaveBeenCalledWith(collector, { extra: 1 });
    expect(session.status).toBe('ready');
  });

  it('awaits a collector that attaches after tokenize is called', async () => {
    const session = createFormSession(fakeAdapter(), { readyTimeoutMs: 1000 });
    const pending = session.tokenize();
    setTimeout(() => session.attachCollector({}), 5);
    await expect(pending).resolves.toEqual(success);
  });

  it('answers sdk_not_ready if no collector attaches before the timeout', async () => {
    const session = createFormSession(fakeAdapter(), { readyTimeoutMs: 10 });
    const result = await session.tokenize();
    expect(result.status).toBe('error');
    expect(result.vaultType).toBe('vgs');
    expect(errorOf(result)?.code).toBe('sdk_not_ready');
    expect(errorOf(result)?.type).toBe('api_error');
  });

  it('answers tokenization_failed when the host has failed', async () => {
    const session = createFormSession(fakeAdapter(), { readyTimeoutMs: 1000 });
    session.fail(new Error('init blew up'));
    const result = await session.tokenize();
    expect(result.status).toBe('error');
    expect(errorOf(result)?.code).toBe('tokenization_failed');
    expect(errorOf(result)?.message).toMatch(/init blew up/);
  });

  it('maps an adapter rejection to tokenization_failed and recovers status', async () => {
    const session = createFormSession(
      fakeAdapter(async () => {
        throw new Error('tokenization failed');
      })
    );
    session.attachCollector({});
    const result = await session.tokenize();
    expect(result.status).toBe('error');
    expect(errorOf(result)?.code).toBe('tokenization_failed');
    expect(errorOf(result)?.message).toMatch(/tokenization failed/);
    expect(session.status).toBe('ready');
  });

  it('reports tokenizing while the adapter call is in flight, and shares that call', async () => {
    let resolveTokenize!: (r: TokenizeResult) => void;
    const tokenize = jest.fn(
      () => new Promise<TokenizeResult>((r) => (resolveTokenize = r))
    );
    const session = createFormSession(fakeAdapter(tokenize));
    session.attachCollector({});
    const first = session.tokenize();
    const second = session.tokenize();
    expect(session.status).toBe('tokenizing');
    expect(second).toBe(first);
    resolveTokenize(success);
    await first;
    expect(tokenize).toHaveBeenCalledTimes(1);
    expect(session.status).toBe('ready');
  });
});

import { describe, it, expect } from '@jest/globals';

import { Hyperswitch, init } from '../init';

describe('Hyperswitch.init', () => {
  it('resolves to the instance the session takes', async () => {
    const instance = await init({
      publishableKey: 'pk_test',
      profileId: 'pro_456',
    });
    expect(instance).toMatchObject({
      publishableKey: 'pk_test',
      profileId: 'pro_456',
    });
    expect(typeof instance.initPaymentMethodSession).toBe('function');
  });

  it('is reachable as Hyperswitch.init, as the checkout SDK spells it', async () => {
    await expect(
      Hyperswitch.init({ publishableKey: 'pk_test' })
    ).resolves.toMatchObject({ publishableKey: 'pk_test' });
  });

  it('carries the endpoint configuration', async () => {
    await expect(
      init({
        publishableKey: 'pk_test',
        platformPublishableKey: 'pk_platform',
        environment: 'PROD',
        customEndpoints: { commonEndpoint: 'https://vault.acme.test/api' },
      })
    ).resolves.toMatchObject({
      publishableKey: 'pk_test',
      platformPublishableKey: 'pk_platform',
      environment: 'PROD',
      customEndpoints: { commonEndpoint: 'https://vault.acme.test/api' },
    });
  });

  it('omits a blank member rather than carrying undefined', async () => {
    const instance = await init({
      publishableKey: '  pk_test  ',
      profileId: '   ',
    });
    expect(instance.publishableKey).toBe('pk_test');
    expect('profileId' in instance).toBe(false);
    expect('environment' in instance).toBe(false);
  });

  it('rejects a missing publishable key', async () => {
    await expect(init({ publishableKey: '  ' })).rejects.toThrow(
      /non-empty publishableKey/
    );
  });
});

import { describe, it, expect } from '@jest/globals';

import {
  descriptorKey,
  readFieldDescriptor,
  readFormDescriptor,
} from '../descriptor';
import {
  PROTOCOL_VERSION,
  SURFACE_TYPE_FIELD,
  SURFACE_TYPE_FORM,
} from '../protocol';

const form = {
  type: SURFACE_TYPE_FORM,
  protocolVersion: PROTOCOL_VERSION,
  formId: 'form-1',
  hyper: { publishableKey: 'pk_snd_1' },
  sdkAuthorization: 'auth',
};

const field = {
  type: SURFACE_TYPE_FIELD,
  protocolVersion: PROTOCOL_VERSION,
  formId: 'form-1',
  elementType: 'cardNumber',
};

const messageOf = (result: { ok: boolean; message?: string }) =>
  result.ok ? null : result.message;

describe('readFormDescriptor', () => {
  it('accepts a session to look up, or vault details handed over directly', () => {
    expect(readFormDescriptor(form).ok).toBe(true);

    const { sdkAuthorization: _sdkAuthorization, ...withoutAuth } = form;
    expect(messageOf(readFormDescriptor(withoutAuth))).toMatch(
      /sdkAuthorization or vaultDetails/
    );
    expect(
      readFormDescriptor({
        ...withoutAuth,
        vaultDetails: { vaultType: 'vgs', vaultData: {} },
      }).ok
    ).toBe(true);
  });

  it('needs a publishable key and a form id', () => {
    expect(
      messageOf(readFormDescriptor({ ...form, hyper: { publishableKey: ' ' } }))
    ).toMatch(/publishableKey/);
    expect(messageOf(readFormDescriptor({ ...form, formId: '' }))).toMatch(
      /formId/
    );
  });

  it('accepts an older protocol and refuses a newer one', () => {
    expect(readFormDescriptor({ ...form, protocolVersion: 1 }).ok).toBe(true);
    expect(
      messageOf(
        readFormDescriptor({ ...form, protocolVersion: PROTOCOL_VERSION + 1 })
      )
    ).toMatch(/Update the SDK bundle/);
    expect(
      messageOf(readFormDescriptor({ ...form, protocolVersion: '1' }))
    ).toMatch(/positive integer/);
  });
});

describe('readFieldDescriptor', () => {
  it('accepts a known field and refuses an unknown one', () => {
    expect(readFieldDescriptor(field).ok).toBe(true);
    expect(
      messageOf(readFieldDescriptor({ ...field, elementType: 'cardPin' }))
    ).toMatch(/Unknown elementType/);
    expect(messageOf(readFieldDescriptor(form))).toMatch(/Unsupported type/);
  });
});

describe('descriptorKey', () => {
  it('is equal for equal props, whatever object carries them', () => {
    expect(descriptorKey({ ...form })).toBe(descriptorKey({ ...form }));
    expect(descriptorKey({ ...form, formId: 'form-2' })).not.toBe(
      descriptorKey(form)
    );
  });
});

describe('withEnvironment', () => {
  const { withEnvironment } = require('../forms') as typeof import('../forms');

  it('goes by the key, as the payments SDK does', () => {
    expect(withEnvironment({ publishableKey: 'pk_snd_abc' }).environment).toBe(
      'SANDBOX'
    );
    expect(withEnvironment({ publishableKey: 'pk_prd_abc' }).environment).toBe(
      'PROD'
    );
  });

  it('is not misled by a default: Android names PROD unless told otherwise', () => {
    expect(
      withEnvironment({ publishableKey: 'pk_snd_abc', environment: 'PROD' })
        .environment
    ).toBe('SANDBOX');
  });

  it('keeps INTEG, which no key can tell apart from sandbox', () => {
    expect(
      withEnvironment({ publishableKey: 'pk_snd_abc', environment: 'INTEG' })
        .environment
    ).toBe('INTEG');
  });
});

import { describe, it, expect } from '@jest/globals';

import { FieldEvent, FormEvent } from '../protocol';
import { WIRE_SHAPES, toWire } from '../wire';

const PAN = '4242424242424242';
const CVC = '737';

const fieldChange = {
  elementType: 'cardNumber',
  empty: false,
  complete: true,
  valid: true,
  brand: 'visa',
  touched: true,
};

describe('what may leave the engine', () => {
  it('has a rule for every event the protocol names', () => {
    const named = [...Object.values(FieldEvent), ...Object.values(FormEvent)];
    expect(Object.keys(WIRE_SHAPES).sort()).toEqual([...named].sort());
  });

  it('drops any key a field change is not allowed to carry', () => {
    const sent = toWire(FieldEvent.Change, {
      ...fieldChange,
      value: PAN,
      cardNumber: PAN,
      cvc: CVC,
      raw: { number: PAN },
    });

    expect(sent).toEqual(fieldChange);
    expect(JSON.stringify(sent)).not.toContain(PAN);
    expect(JSON.stringify(sent)).not.toContain(CVC);
  });

  it('applies the same rule inside a form change, at every level', () => {
    const sent = toWire(FormEvent.Change, {
      elementType: 'cardForm',
      eventName: 'cardDetailsChange',
      payload: { bin: '424242', last4: '4242', brand: 'visa', number: PAN },
      complete: true,
      valid: true,
      fields: {
        cardNumber: { ...fieldChange, value: PAN },
        cardCvc: { ...fieldChange, elementType: 'cardCvc', value: CVC },
      },
      state: { cardNumber: PAN, cvc: CVC },
    });

    expect(sent).toEqual({
      elementType: 'cardForm',
      eventName: 'cardDetailsChange',
      payload: { bin: '424242', last4: '4242', brand: 'visa' },
      complete: true,
      valid: true,
      fields: {
        cardNumber: fieldChange,
        cardCvc: { ...fieldChange, elementType: 'cardCvc' },
      },
    });
    expect(JSON.stringify(sent)).not.toContain(PAN);
  });

  it('keeps only the message of an error, never the thing that failed', () => {
    expect(
      toWire(FormEvent.Error, {
        message: 'The vault refused the card.',
        request: { body: { card_number: PAN } },
      })
    ).toEqual({ message: 'The vault refused the card.' });
  });

  it('passes a tokenize result whole, as in-process callers receive it', () => {
    const result = {
      status: 'success',
      vaultType: 'vgs',
      data: { tokens: { card_number: 'tok_1' } },
      card: { last4: '4242', brand: 'visa' },
    };
    expect(
      toWire(FormEvent.CommandResult, {
        commandId: 'c1',
        name: 'tokenize',
        ok: true,
        result,
        debug: { number: PAN },
      })
    ).toEqual({ commandId: 'c1', name: 'tokenize', ok: true, result });
  });

  it('sends only what a native map can hold', () => {
    expect(
      toWire(FieldEvent.Change, {
        ...fieldChange,
        brand: undefined,
        error: undefined,
      })
    ).toEqual({
      elementType: 'cardNumber',
      empty: false,
      complete: true,
      valid: true,
      touched: true,
    });

    const circular: Record<string, unknown> = { commandId: 'c1' };
    circular.result = circular;
    expect(toWire(FormEvent.CommandResult, circular)).toEqual({});
  });
});

import { describe, it, expect, jest, beforeEach } from '@jest/globals';

import { hostBridge } from '../bridge';
import { FieldEvent, FormEvent } from '../protocol';

const mockEmitFieldEvent = jest.fn();
const mockEmitFormEvent = jest.fn();
let mockCommandHandler: ((event: unknown) => void) | null = null;
const mockRemove = jest.fn(() => {
  mockCommandHandler = null;
});

jest.mock('../../../specs/NativeHyperPaymentMethods', () => ({
  __esModule: true,
  default: {
    emitFieldEvent: (...args: unknown[]) => mockEmitFieldEvent(...args),
    emitFormEvent: (...args: unknown[]) => mockEmitFormEvent(...args),
    onCommand: (handler: (event: unknown) => void) => {
      mockCommandHandler = handler;
      return { remove: mockRemove };
    },
  },
}));

beforeEach(() => {
  mockEmitFieldEvent.mockClear();
  mockEmitFormEvent.mockClear();
  mockRemove.mockClear();
});

describe('hostBridge', () => {
  it('sends events through its own module, filtered by the wire rules', () => {
    hostBridge.emitField(7, FieldEvent.Change, {
      elementType: 'cardCvc',
      empty: false,
      complete: true,
      valid: true,
      touched: true,
      value: '737',
    });
    expect(mockEmitFieldEvent).toHaveBeenCalledWith(7, 'PM_FIELD_CHANGE', {
      elementType: 'cardCvc',
      empty: false,
      complete: true,
      valid: true,
      touched: true,
    });

    hostBridge.emitForm(5, FormEvent.Error, {
      message: 'nope',
      cause: { number: '4242424242424242' },
    });
    expect(mockEmitFormEvent).toHaveBeenCalledWith(5, 'PM_FORM_ERROR', {
      message: 'nope',
    });
  });

  it('reads providerData out of its JSON text', () => {
    const listener = jest.fn();
    hostBridge.onCommand(listener);

    mockCommandHandler?.({
      rootTag: 5,
      formId: 'form-1',
      commandId: 'c1',
      name: 'tokenize',
      providerData: '{"routeId":"r_1"}',
    });
    expect(listener).toHaveBeenLastCalledWith({
      rootTag: 5,
      formId: 'form-1',
      commandId: 'c1',
      name: 'tokenize',
      elementType: undefined,
      providerData: { routeId: 'r_1' },
    });

    mockCommandHandler?.({
      rootTag: 5,
      formId: 'form-1',
      commandId: 'c2',
      name: 'tokenize',
      providerData: '{not json',
    });
    expect(listener).toHaveBeenLastCalledWith(
      expect.objectContaining({ commandId: 'c2', providerData: undefined })
    );
  });

  it('drops a command nobody could be answered for, and stops when asked', () => {
    const listener = jest.fn();
    const stop = hostBridge.onCommand(listener);

    mockCommandHandler?.({ formId: 'form-1', commandId: 'c1', name: 'tokenize' });
    mockCommandHandler?.({
      rootTag: 5,
      formId: 'form-1',
      commandId: '',
      name: 'tokenize',
    });
    expect(listener).not.toHaveBeenCalled();

    stop();
    expect(mockRemove).toHaveBeenCalledTimes(1);
  });
});

